const input = $input.first().json;
const body = input.body ?? input;
const headers = input.headers ?? {};
const messages = Array.isArray(body.messages) ? body.messages : [];

// How many previous messages of the request are replayed to the agent. Twenty turns is far
// more than the window buffer ever held and still a bounded prompt.
const HISTORY_LIMIT = 40;

const asText = (content) => {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content
      .map((part) => (typeof part === 'string' ? part : (part && part.text) || ''))
      .join(' ');
  }
  return '';
};

// FNV-1a instead of require('crypto'): the Code sandbox disallows Node builtins, and a session
// key only has to stay stable across the turns of one conversation, not be cryptographic.
const fnv1a = (text, offsetBasis) => {
  let hash = offsetBasis >>> 0;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
};

const digest = (text) =>
  fnv1a(text, 2166136261) +
  fnv1a(text, 40389) +
  fnv1a(text.length + ':' + text, 3735928559);

// Incoming header names arrive lowercased, but fall back to a case-insensitive lookup so a
// proxy that preserves the original casing does not silently drop the identifier.
const headerValue = (name) => {
  const direct = headers[name];
  if (typeof direct === 'string') return direct;
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === name);
  return typeof headers[key] === 'string' ? headers[key] : '';
};

// The only trusted identity in the system. It is whoever the chat frontend authenticated,
// injected as a header; it never comes from the conversation, so nothing the customer types
// and nothing the model decides can change it. Empty when the caller sent none, which the
// microservice refuses rather than treating as permission.
const endUserId = headerValue('x-end-user-id').trim();

const firstUserMessage = messages.find((message) => message && message.role === 'user');
const seed = asText((firstUserMessage || messages[0] || {}).content).trim();

const bodyConversationId =
  typeof body.conversation_id === 'string' ? body.conversation_id : '';
const conversationId = (headerValue('x-conversation-id') || bodyConversationId).trim();

let executionId = '';
try {
  executionId = String($execution.id ?? '');
} catch (error) {
  executionId = '';
}

// Three tiers, most trustworthy first. A caller-supplied conversation id keeps two customers
// who open with the same greeting apart; the content hash keeps plain curl testing stable
// across turns; the execution id stops content-less requests from sharing one bucket.
let sessionId;
let sessionSource;
if (conversationId) {
  sessionId = 'cid-' + digest(conversationId);
  sessionSource = 'conversation_id';
} else if (seed) {
  sessionId = digest(seed);
  sessionSource = 'content_hash';
} else {
  sessionId = 'exec-' + (executionId || digest(String(Date.now()) + Math.random()));
  sessionSource = 'execution';
}

// An OpenAI chat/completions client owns the conversation and resends all of it every turn, so
// the request itself is the authoritative history: it survives an n8n restart and always
// matches what the customer has on screen. Take the last user message as the question and
// everything before it as the transcript.
const turns = messages
  .filter((message) => message && (message.role === 'user' || message.role === 'assistant'))
  .map((message) => ({ role: message.role, text: asText(message.content).trim() }))
  .filter((turn) => turn.text);

let currentIndex = -1;
for (let i = turns.length - 1; i >= 0; i--) {
  if (turns[i].role === 'user') {
    currentIndex = i;
    break;
  }
}
if (currentIndex === -1) currentIndex = turns.length - 1;

const lastMessage = currentIndex >= 0 ? turns[currentIndex].text : '';
const history = turns.slice(0, Math.max(0, currentIndex)).slice(-HISTORY_LIMIT);

const transcript = history
  .map((turn) => (turn.role === 'user' ? 'Customer: ' : 'Agent: ') + turn.text)
  .join('\n');

const agentInput = history.length
  ? 'CONVERSATION SO FAR (already on the customer screen; this is your memory of it):\n' +
    transcript +
    '\n\nCURRENT MESSAGE FROM THE CUSTOMER:\n' +
    lastMessage
  : lastMessage;

// The in-process window buffer is only a fallback for callers that send a single message and
// expect the server to remember, because it lives in the n8n process and dies with it. When
// the request carries its own history, that history wins and the buffer is bypassed with a
// per-execution key, so the same turns are never fed to the model twice.
const memoryKey = history.length
  ? sessionId + '#' + (executionId || digest(agentInput))
  : sessionId;

return [
  {
    json: {
      session_id: sessionId,
      session_source: sessionSource,
      end_user_id: endUserId,
      memory_key: memoryKey,
      agent_input: agentInput,
      last_message: lastMessage,
      history_count: history.length,
      message_count: messages.length,
    },
  },
];
